// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// A CONSTRUCT template gives Alice a blank address that is not in the repository. Expand must still load the address
// the repository stores (a blank node it certifies), through the same predicate.
const REPOSITORY_ID = uniqueRepositoryId('graph-blank-expand');
const EX = 'http://example.org/blank-expand/';
const DATA = `
@prefix ex: <${EX}> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice rdfs:label "Alice" ; ex:address _:stored .
_:stored ex:city "Oslo" .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph blank expand')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, { headers: { 'Content-Type': 'text/turtle' }, data: DATA });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test('Expand loads a stored blank neighbour through a predicate a template blank node also uses', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
    await explorer.locator('#sparql').fill(
        `CONSTRUCT { <${EX}alice> <${EX}address> [ <${EX}street> "Template street" ] } WHERE {}`);
    await explorer.getByRole('button', { name: 'Run query' }).click();
    await expect(explorer.getByRole('button', { name: 'Run query' })).toBeEnabled({ timeout: 30000 });
    await explorer.getByRole('button', { name: 'Close query editor' }).click();
    const addresses = () => page.evaluate(() => [...document.querySelectorAll('.graph-explorer .edge title')]
        .filter((title) => / — address → /.test(title.textContent ?? '')).length);
    await expect.poll(addresses, { timeout: 30000 }).toBe(1);

    const alice = explorer.locator('.graph-node').filter({ has: page.locator('text', { hasText: /^alice$/i }) }).first();
    await alice.dblclick();

    // The template's address stays; the stored one arrives next to it.
    await expect.poll(addresses, { timeout: 30000 }).toBe(2);
});
